<?php
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$t=fn($k)=>$this->getObject('language','language')->code2Txt('mod_photogallery_'.$k,'photogallery');$u=fn($p)=>html_entity_decode($this->uri($p,'photogallery'),ENT_QUOTES,'UTF-8');$s=$this->getObject('photoservice','photogallery');$icon=fn($n)=>$this->getObject('iconservice','ui')->render($n,['decorative'=>true]);
$this->appendArrayVar('headerParams','<script defer src="'.$e($this->getResourceUri('refresh.js','photogallery')).'"></script>');
if(!$photoGallery){echo '<p>'.$e($t('missing')).'</p>';return;}$g=$photoGallery;$destination=['module'=>'photogallery','id'=>$g['id']];if($photoPage>1)$destination['page']=$photoPage;foreach($this->getObject('pagemetadata','ui')->build($g['title'],$t('intro'),$destination) as $key=>$value)$this->setVar($key,$value);
?>
<main class="chisimba-content-composition">
<header class="chisimba-form-card chisimba-form-card--wide"><h1><?= $e($g['title']) ?></h1><p><?= $e($t('intro')) ?></p><div class="chisimba-form-actions"><?= $this->getObject('contextualhelp','help')->show('photogallery','viewing',true) ?><a class="button" href="<?= $e($g['source_url']) ?>" rel="noopener noreferrer"><?= $icon('external-link') ?><?= $e($t('source')) ?></a></div>
<?php if($s->canManage()): ?><p><?= $e($t('cached').' '.$g['fetched'].' UTC') ?></p><?php if($s->enabled()): ?><form method="post" data-photo-refresh data-progress="<?= $e($t('refreshing')) ?>" action="<?= $e($u(['action'=>'refresh','id'=>$g['id']])) ?>"><input type="hidden" name="csrf_token" value="<?= $e($photoToken) ?>"><button class="button" type="submit"><?= $icon('refresh-cw') ?><?= $e($t('refresh')) ?></button><p role="status" aria-live="polite"></p></form><?php else: ?><p><?= $e($t('disabled')) ?></p><?php endif; ?><?php endif; ?>
<?php if($photoNotice): ?><p role="status"><?= $e($t($photoNotice)) ?></p><?php endif; ?></header>
