<div class="chisimba-photo-grid">
<?php foreach($photoItems as $item): ?><figure class="chisimba-form-card chisimba-photo-card"><a href="<?= $e($item['url']) ?>" rel="noopener noreferrer"><img src="<?= $e($item['image']) ?>" alt="<?= $e($item['title']) ?>" loading="lazy" decoding="async" referrerpolicy="no-referrer"></a><figcaption><p><?= $e($item['title']) ?></p><p><?= $e($t('by')) ?> <a href="<?= $e($item['owner_url']) ?>" rel="noopener noreferrer"><?= $e($item['credit']) ?></a> · <a href="<?= $e($item['url']) ?>" rel="noopener noreferrer"><?= $e(ucfirst($g['provider'])) ?></a></p></figcaption></figure><?php endforeach; ?>
</div><nav class="chisimba-form-actions" aria-label="<?= $e($t('pages')) ?>"><?php if($photoPage>1): ?><a class="button" href="<?= $e($u(['id'=>$g['id'],'page'=>$photoPage-1])) ?>"><?= $icon('chevron-left') ?><?= $e($t('previous')) ?></a><?php endif; ?><?php if($photoMore): ?><a class="button" href="<?= $e($u(['id'=>$g['id'],'page'=>$photoPage+1])) ?>"><?= $e($t('next')) ?><?= $icon('chevron-right') ?></a><?php endif; ?></nav>
<p><?= $e($t('provided')) ?> <a href="<?= $e($g['source_url']) ?>"><?= $e(ucfirst($g['provider'])) ?></a>. <?= $e($t($g['provider']==='flickr'?'feed_limit':'search_limit')) ?></p></main>
